package dev.dwmir.lib;
import dev.dwmir.lib.api.*;import net.minecraft.client.gui.*;import net.minecraft.client.gui.screen.Screen;import net.minecraft.client.gui.widget.TextFieldWidget;import net.minecraft.text.Text;import java.util.*;
public final class ProfilesScreen extends Screen {
 private final Screen parent;private java.util.List<ProfileStore.Profile> profiles=List.of();private int x,y,w,h,offset;private String name="",notice="";private TextFieldWidget field;
 public ProfilesScreen(Screen parent){super(net.minecraft.text.Text.literal("Profiles"));this.parent=parent;}
 protected void init(){clearChildren();w=Math.min(730,width-32);h=Math.min(450,height-32);x=(width-w)/2;y=(height-h)/2;profiles=ProfileStore.list();field=addDrawableChild(new TextFieldWidget(textRenderer,x+22,y+64,w-182,26,net.minecraft.text.Text.literal("Profile name")));field.setMaxLength(64);field.setText(name);field.setPlaceholder(net.minecraft.text.Text.literal("Name this setup..."));field.setChangedListener(v->name=v);addDrawableChild(new GlassButton(x+w-146,y+64,124,26,net.minecraft.text.Text.literal("Save all mods"),()->{try{var p=ProfileStore.capture(name);notice="Saved "+p.mods().size()+" mods";offset=0;init();}catch(Exception e){notice=e.getMessage();}}));int count=Math.max(1,(h-170)/76);offset=Math.clamp(offset,0,Math.max(0,profiles.size()-count));for(int i=offset;i<Math.min(profiles.size(),offset+count);i++){var p=profiles.get(i);int yy=y+112+(i-offset)*76;addDrawableChild(new GlassButton(x+w-105,yy+16,80,28,net.minecraft.text.Text.literal("Load"),()->{try{int n=ProfileStore.apply(p);notice="Loaded "+p.name()+" / "+n+" mods";}catch(Exception e){notice="Could not load profile";org.slf4j.LoggerFactory.getLogger("dwmirlib").error("Profile load failed",e);}}));}addDrawableChild(new GlassButton(x+22,y+h-42,40,25,net.minecraft.text.Text.literal("<"),()->{offset=Math.max(0,offset-count);init();}));addDrawableChild(new GlassButton(x+68,y+h-42,40,25,net.minecraft.text.Text.literal(">"),()->{offset+=count;init();}));addDrawableChild(new GlassButton(x+w-105,y+h-42,80,25,net.minecraft.text.Text.literal("Done"),this::close));}
 public void renderBackground(DrawContext d,int mx,int my,float dt){}
 public void render(DrawContext d,int mx,int my,float dt){GlassUi.round(d,x,y,w,h,24,GlassUi.PANEL);d.drawText(textRenderer,"Profiles",x+22,y+22,GlassUi.TEXT,false);d.drawText(textRenderer,"Save and restore all loaded dwmir mods together.",x+22,y+40,GlassUi.MUTED,false);int count=Math.max(1,(h-170)/76);for(int i=offset;i<Math.min(profiles.size(),offset+count);i++){var p=profiles.get(i);int yy=y+112+(i-offset)*76;GlassUi.rawRound(d,x+18,yy,w-36,66,16,0x20ffffff);d.drawText(textRenderer,textRenderer.trimToWidth(p.name(),w-160),x+32,yy+12,GlassUi.TEXT,false);String mods=String.join(" / ",p.mods().stream().map(ProfileStore.Mod::name).toList());var lines=textRenderer.wrapLines(net.minecraft.text.Text.literal(mods),w-165);for(int j=0;j<Math.min(2,lines.size());j++)d.drawText(textRenderer,lines.get(j),x+32,yy+29+j*12,GlassUi.MUTED,false);}if(profiles.isEmpty())GlassUi.label(d,"No saved profiles yet",x+20,y+150,w-40,60,GlassUi.MUTED);GlassUi.label(d,notice.isEmpty()?profiles.size()+" profiles":notice,x+118,y+h-42,w-240,25,GlassUi.MUTED);super.render(d,mx,my,dt);}
 public void close(){client.setScreen(parent);}public boolean shouldPause(){return false;}
}
